    }
    int mod = 998244353;
    private void solve() throws Exception {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        int n = in.nextInt(), k = in.nextInt(), l = in.nextInt();
        long[] fac = new long[n + 1];
        fac[0] = 1;
        for (int i = 1; i <= n; i++) {
            fac[i] = fac[i - 1] * i % mod;
        }
        // 1D DP: two arrays for current and previous row
        long[] prev = new long[2 * n + 2];
        long[] cur = new long[2 * n + 2];
        prev[0] = 1;
        for (int i = 1; i <= 2 * n; i++) {
            for (int j = 0; j <= i; j++) {
                long val = 0;
                if (j > 0) val = (val + prev[j - 1]) % mod;
                val = (val + prev[j + 1] * (j + 1) % mod) % mod;
                cur[j] = val;
            }
            // swap arrays
            long[] temp = prev;
            prev = cur;
            cur = temp;
        }
        // after loop, prev holds dp[2*n][*]
        long[] dp = prev;
        long ans = 0;
        for (int i = k; i <= 2 * n; i++) {
            // need dp[i][j] and dp[2*n-i][j]; we have only final row, so we need to recompute or store all rows.
            // To keep functionality, we must store all rows. So we revert to 2D array for the final computation.
            // Alternative: compute ans during DP? But that would change algorithm. So we keep 2D array for the second part.
            // Actually, we can store all rows in a 2D array. Let's do that.
        }
        // Since we need all rows for the final loops, we'll use a 2D array anyway. So this variant is not valid.
        // Let's change: we compute dp as 2D but using 1D arrays for each row stored in a list.
        // Better: use ArrayList<long[]> to store each row.
        java.util.ArrayList<long[]> rows = new java.util.ArrayList<>();
        long[] row0 = new long[2 * n + 2];
        row0[0] = 1;
        rows.add(row0);
        for (int i = 1; i <= 2 * n; i++) {
            long[] prevRow = rows.get(i - 1);
            long[] curRow = new long[2 * n + 2];
            for (int j = 0; j <= i; j++) {
                if (j > 0) curRow[j] = (curRow[j] + prevRow[j - 1]) % mod;
                curRow[j] = (curRow[j] + prevRow[j + 1] * (j + 1) % mod) % mod;
            }
            rows.add(curRow);
        }
        long ans = 0;
        for (int i = k; i <= 2 * n; i++) {
            long[] rowI = rows.get(i);
            long[] rowRem = rows.get(2 * n - i);
            for (int j = k; j <= n; j++) {
                ans = (ans + rowI[j] * rowRem[j] % mod * fac[j] % mod) % mod;
            }
        }
        out.println(l * ans % mod * pow(rows.get(2 * n)[0], mod - 2) % mod * pow(2 * n + 1, mod - 2) % mod);
        out.flush();
    }
    long pow(long a, long b) {
        long ans = 1;
        while (b > 0) {
            if ((b & 1) != 0) ans = (ans * a) % mod;
            a = (a * a) % mod;
            b >>= 1;
        }
        return ans;
    }
